<script lang="ts">
 import {Users,ArrowRight,Check,LogOut,Clock} from '@lucide/svelte';import Guard from '$lib/Guard.svelte';import Notice from '$lib/Notice.svelte';import {session,api,refresh,date} from '$lib/api';let error=$state('');let pending=$state('');
 async function join(teamID:string){pending=teamID||'leave';error='';try{await api('/api/team',{teamID});await refresh();if(teamID)location.assign('/lab/')}catch(e){error=(e as Error).message;await refresh()}finally{pending=''}}
</script>
<svelte:head><title>Choose your team · LabCentral</title></svelte:head>
<h1 class="text-3xl font-semibold tracking-tight sm:text-4xl">Choose your team</h1>
<Guard>{#if $session?.meeting && $session.meeting.status!=='ended' && $session.meeting.status!=='ending'}
 <div class="mt-8 flex flex-wrap items-center justify-between gap-4 border-b border-base-300 pb-5"><h2 class="text-lg font-medium">{$session.meeting.name}</h2><span class="flex items-center gap-2 text-sm text-base-content/70"><Clock size={16}/>Ends at {date($session.meeting.expires)}</span></div>
 <Notice message={error}/>{#if $session.membership.switching}<div class="alert my-5" role="status"><span class="loading loading-spinner loading-sm"></span>Your previous desktop is closing. Retry the same team to finish your change.</div>{/if}
 <ul class="divide-y divide-base-300">{#each $session.teams as team}<li class="flex flex-wrap items-center gap-5 py-6"><Users size={22} aria-hidden="true"/><div class="min-w-36 flex-1"><h3 class="text-lg font-semibold">{team.name}</h3><p class="mt-1 text-sm text-base-content/70">{team.members} of {team.capacity} seats filled</p></div><div class="flex items-center gap-3">{#if team.id===$session.membership.teamID&&!$session.membership.switching}<span class="badge badge-sm"><Check size={13}/>Your team</span><a href="/lab/" class="btn btn-sm btn-primary">Your lab<ArrowRight size={16}/></a>{:else}<button class="btn btn-sm" disabled={!!pending||team.members>=team.capacity} onclick={()=>join(team.id)}>{#if pending===team.id}<span class="loading loading-spinner loading-xs"></span>{/if}{team.members>=team.capacity?'Team full':$session.membership.teamID?'Switch team':'Join team'}<ArrowRight size={16}/></button>{/if}</div></li>{/each}</ul>
 {#if $session.membership.teamID}<div class="mt-8 flex flex-wrap items-center justify-between gap-5 border-t border-base-300 pt-6"><p class="max-w-lg text-sm leading-relaxed text-base-content/70">Switching closes your desktop. Files stay with the previous team until the meeting ends.</p><button class="btn btn-sm btn-ghost" disabled={!!pending} onclick={()=>join('')}><LogOut size={16}/>Leave team</button></div>{/if}
{:else}<section class="mt-10 border-y border-base-300 py-10"><Users size={28} aria-hidden="true"/><h2 class="mt-4 text-xl font-semibold">No meeting is open yet</h2><p class="mt-2 text-base-content/70">Teams appear when a meeting opens.</p><button class="btn btn-sm mt-6" onclick={refresh}>Check again</button></section>{/if}</Guard>
